#include <iostream>
#include <string>

int main() {
    std::string s;
    std::getline(std::cin, s);
    std::string output = "";
    bool found_at_symbol = false;
    size_t index_counter = 0;
    while (index_counter < s.length()) {
        if (index_counter != 0 && index_counter + 3 <= s.length() && s.substr(index_counter, 3) == "dot") {
            output += '.';
            index_counter += 2;
        } else if (index_counter != 0 && index_counter + 2 <= s.length() && !found_at_symbol && s.substr(index_counter, 2) == "at") {
            output += '@';
            found_at_symbol = true;
            index_counter += 1;
        } else {
            output += s[index_counter];
        }
        index_counter += 1;
    }
    std::cout << output << std::endl;
    return 0;
}
